const CACHE='force-multiplier-22-1-native-candidate';
const FILES=['./native.js','./native.css','./about.html','./licenses.html','./review.html','./','./index.html','./game.css','./skill-games.css','./game.js','./game-rules.js','./game-worlds.js','./pack-analysis.js','./pack-documentation.js','./pack-database.js','./pack-integrity.js','./courses.html','./styles.css','./core.js','./scheduling.js','./analysis.js','./records.js','./app.js','./icon.svg','./icon-192.png','./icon-512.png','./icon-maskable.png','./manifest.webmanifest'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting())));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('force-multiplier-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{if(event.request.method!=='GET'||new URL(event.request.url).origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();caches.open(CACHE).then(c=>c.put(event.request,copy));}return response;}).catch(()=>caches.match(event.request).then(r=>r||(event.request.mode==='navigate'?caches.match('./index.html'):Response.error()))));});
